package com.example.sumayerestaurant.data.model; import com.google.gson.annotations.SerializedName; import java.math.BigDecimal; public class ProfitLoss{@SerializedName("sales")private BigDecimal sales;@SerializedName("operatingExpenses")private BigDecimal operatingExpenses;@SerializedName("estimatedProfit")private BigDecimal estimatedProfit;@SerializedName("label")private String label;public BigDecimal getSales(){return sales;}public BigDecimal getOperatingExpenses(){return operatingExpenses;}public BigDecimal getEstimatedProfit(){return estimatedProfit;}public String getLabel(){return label;}}
